#!/usr/bin/env bash
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$REPO_DIR"

if [ -d ".venv" ]; then
  source .venv/bin/activate
fi

# Find the most recently modified spoken digest text file in ~/Downloads
LATEST_TXT=$(ls -t ~/Downloads/*digest*.txt 2>/dev/null | head -n 1 || true)

if [ -z "$LATEST_TXT" ]; then
  echo "No *digest*.txt file found in ~/Downloads."
  exit 1
fi

echo "Using digest file: $LATEST_TXT"
python briefing.py --file "$LATEST_TXT"

# Play the newest cached MP3 generated by briefing.py
LATEST_MP3=$(ls -t audio_cache/briefing_*.mp3 2>/dev/null | head -n 1 || true)

if [ -z "$LATEST_MP3" ]; then
  echo "No MP3 found in audio_cache/."
  exit 1
fi

echo "Playing: $LATEST_MP3"
afplay "$LATEST_MP3"
